import { IngestPipeline } from "@514labs/moose-lib";

// User Activity data model
export interface UserActivity {
  event_id: string;
  event_ts: Date;
  user_id: string;
  action: string;
  duration_ms: number;
}

// Create ingestion pipeline with optimized ordering for query patterns
export const UserActivityPipeline = new IngestPipeline<UserActivity>("UserActivity", {
  table: {
    orderByFields: ["user_id", "event_ts"] // Optimize for user-based queries and time-based filtering
  },
  stream: true,
  ingestApi: true,
});

const fs = require('fs');
const https = require('http'); // Using http for localhost

// Read and parse CSV data
const csvData = fs.readFileSync('/data/samples/user_activity_sample.csv', 'utf8');
const lines = csvData.trim().split('\n');
const headers = lines[0].split(',');

// Convert CSV to JSON and post to Moose
const records = [];

for (let i = 1; i < lines.length; i++) {
  const values = lines[i].split(',');

  if (values.length === headers.length) {
    const record = {
      event_id: values[0],
      event_ts: values[1],
      user_id: values[2],
      action: values[3],
      duration_ms: values[4] === '' || values[4] === '0' || !values[4] ? 0 : parseInt(values[4])
    };
    records.push(record);
  }
}

console.log(`Loaded ${records.length} records from CSV`);

// Function to post a single record
async function postRecord(record) {
  return new Promise((resolve, reject) => {
    const postData = JSON.stringify(record);

    const options = {
      hostname: 'localhost',
      port: 4000,
      path: '/ingest/UserActivity',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(postData)
      }
    };

    const req = https.request(options, (res) => {
      let body = '';
      res.on('data', (chunk) => body += chunk);
      res.on('end', () => {
        if (res.statusCode === 200) {
          resolve(body);
        } else {
          reject(new Error(`HTTP ${res.statusCode}: ${body}`));
        }
      });
    });

    req.on('error', reject);
    req.write(postData);
    req.end();
  });
}

// Load all records
async function loadAllRecords() {
  let successCount = 0;
  let errorCount = 0;

  for (const record of records) {
    try {
      await postRecord(record);
      successCount++;
      console.log(`✓ Loaded record ${record.event_id}`);
    } catch (error) {
      errorCount++;
      console.error(`✗ Failed to load record ${record.event_id}:`, error.message);
    }
  }

  console.log(`\nSummary: ${successCount} successful, ${errorCount} failed`);
}

// Execute the loading
loadAllRecords().catch(console.error);

